module TrafficOptimizer (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] t,\n    input wire [3:0] n,\n    input wire [7:0] car_direction,\n    input wire [135:0] car_arrival,\n    input wire [95:0] car_irritation,\n    output reg [3:0] result,\n    output reg done\n);\n\n// State encoding\nlocalparam [3:0] IDLE         = 4'd0;\nlocalparam [3:0] PREPARE      = 4'd1;\nlocalparam [3:0] DP_LOOP      = 4'd2;\nlocalparam [3:0] UPDATE_STATE = 4'd3;\nlocalparam [3:0] FIND_MIN     = 4'd4;\nlocalparam [3:0] FINISHED     = 4'd5;\n\n// DP memory: 9x9x3 = 243 entries\nreg [20:0] dp [0:242];\n\n// Working registers\nreg [3:0] state;\nreg [3:0] next_state;\nreg [3:0] i, j;\nreg [1:0] d;\nreg [3:0] west_count, east_count;\nreg [15:0] west_arrival [0:7];\nreg [11:0] west_irritation [0:7];\nreg [15:0] east_arrival [0:7];\nreg [11:0] east_irritation [0:7];\nreg [15:0] current_time;\nreg [3:0] current_irr;\nreg [3:0] best_irr;\nreg [3:0] loop_i, loop_j;\nreg [1:0] loop_d;\nreg [3:0] iterate_count;\nreg [15:0] temp_time;\nreg [3:0] temp_irr;\nreg irritation_flag;\n\ninteger idx;\n\nfunction [8:0] state_index;\n    input [3:0] i_val;\n    input [3:0] j_val;\n    input [1:0] d_val;\n    state_index = i_val * 27 + j_val * 3 + d_val;\nendfunction\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 4'd0;\n        west_count <= 4'd0;\n        east_count <= 4'd0;\n        for (idx = 0; idx < 243; idx = idx + 1)\n            dp[idx] <= 21'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= PREPARE;\n                    west_count <= 4'd0;\n                    east_count <= 4'd0;\n                    i <= 4'd0;\n                end\n            end\n\n            PREPARE: begin\n                if (i < n) begin\n                    if (car_direction[i]) begin\n                        west_arrival[west_count] <= car_arrival[16 +: 16];\n                        west_irritation[west_count] <= car_irritation[11 +: 12];\n                        west_count <= west_count + 4'd1;\n                    end else begin\n                        east_arrival[east_count] <= car_arrival[16 +: 16];\n                        east_irritation[east_count] <= car_irritation[11 +: 12];\n                        east_count <= east_count + 4'd1;\n                    end\n                    i <= i + 4'd1;\n                end else begin\n                    // Initialize DP\n                    dp[state_index(0,0,2)] <= {1'b1, 4'd0, 16'd0};\n                    state <= DP_LOOP;\n                    i <= 4'd0;\n                    j <= 4'd0;\n                    d <= 2'd0;\n                end\n            end\n\n            DP_LOOP: begin\n                iterate_count <= 4'd0;\n                if (dp[state_index(i,j,d)][20]) begin\n                    state <= UPDATE_STATE;\n                    current_irr <= dp[state_index(i,j,d)][19:16];\n                    current_time <= dp[state_index(i,j,d)][15:0];\n                    loop_i <= i;\n                    loop_j <= j;\n                    loop_d <= d;\n                end else begin\n                    // Move to next state\n                    if (j == east_count) begin\n                        if (i == west_count) begin\n                            state <= FIND_MIN;\n                        end else begin\n                            i <= i + 4'd1;\n                            j <= 4'd0;\n                        end\n                    end else begin\n                        j <= j + 4'd1;\n                    end\n                    d <= 2'd0;\n                end\n            end\n\n            UPDATE_STATE: begin\n                case (iterate_count)\n                    4'd0: begin  // Update west car\n                        if (loop_i < west_count) begin\n                            // Calculate release time\n                            if (loop_d == 2'b00) temp_time <= current_time + 16'd3;\n                            else temp_time <= current_time + t;\n                            irritation_flag <= (temp_time > west_arrival[loop_i]) ?\n                                 ((temp_time - west_arrival[loop_i]) > west_irritation[loop_i]) : 1'b0;\n                            temp_irr <= current_irr + irritation_flag;\n                            temp_time <= (temp_time > west_arrival[loop_i]) ? temp_time : west_arrival[loop_i];\n                            iterate_count <= 4'd1;\n                        end\n                        else begin\n                            iterate_count <= 4'd2;\n                        end\n                    end\n\n                    4'd1: begin  // Write west update\n                        dp[state_index(loop_i+1, loop_j, 0)] <= {1'b1, temp_irr, temp_time};\n                        iterate_count <= 4'd2;\n                    end\n\n                    4'd2: begin  // Update east car\n                        if (loop_j < east_count) begin\n                            if (loop_d == 2'b01) temp_time <= current_time + 16'd3;\n                            else temp_time <= current_time + t;\n                            irritation_flag <= (temp_time > east_arrival[loop_j]) ?\n                                 ((temp_time - east_arrival[loop_j]) > east_irritation[loop_j]) : 1'b0;\n                            temp_irr <= current_irr + irritation_flag;\n                            temp_time <= (temp_time > east_arrival[loop_j]) ? temp_time : east_arrival[loop_j];\n                            iterate_count <= 4'd3;\n                        end\n                        else begin\n                            iterate_count <= 4'd4;\n                        end\n                    end\n\n                    4'd3: begin  // Write east update\n                        dp[state_index(loop_i, loop_j+1, 1)] <= {1'b1, temp_irr, temp_time};\n                        iterate_count <= 4'd4;\n                    end\n\n                    4'd4: begin  // Restart loop\n                        state <= DP_LOOP;\n                        // Update i/j/d counters\n                        if (loop_j == east_count) begin\n                            if (loop_i == west_count) begin\n                                state <= FIND_MIN;\n                            end else begin\n                                i <= loop_i + 4'd1;\n                                j <= 4'd0;\n                            end\n                        end else begin\n                            i <= loop_i;\n                            j <= loop_j + 4'd1;\n                        end\n                        d <= 2'd0;\n                    end\n                endcase\n            end\n\n            FIND_MIN: begin\n                best_irr <= 4'd8;\n                loop_i <= 4'd0;\n                state <= FINISHED;\n            end\n\n            FINISHED: begin\n                if (loop_i < 3'd3) begin\n                    if (dp[state_index(west_count, east_count, loop_i)][20] &&\n                        (dp[state_index(west_count, east_count, loop_i)][19:16] < best_irr))\n                    begin\n                        best_irr <= dp[state_index(west_count, east_count, loop_i)][19:16];\n                    end\n                    loop_i <= loop_i + 1;\n                end else begin\n                    result <= best_irr;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule